-- Part 270 on a harness database (scripts/sql-harness/run.sh editor leaves harness_editor_psql up): a stand in for the realtime schema Supabase has, then part 270 again as postgres (twice), then who reads what. As supabase_admin: psql -d harness_editor_psql -f scripts/sql-harness/chat-270-check.sql
create schema if not exists realtime;
create table if not exists realtime.messages (id bigserial primary key, topic text, extension text, payload jsonb);
alter table realtime.messages enable row level security;
create or replace function realtime.topic() returns text language sql stable as $$ select current_setting('realtime.topic', true) $$;
grant usage on schema realtime to authenticated, postgres;
alter table realtime.messages owner to postgres;
drop publication if exists supabase_realtime;
create publication supabase_realtime;
alter publication supabase_realtime owner to postgres;
select pg_get_functiondef('auth.uid()'::regprocedure);
grant select, insert on realtime.messages to authenticated;
begin;
insert into auth.users (id, email) values ('11111111-1111-1111-1111-111111111111', 'a@x.test'), ('22222222-2222-2222-2222-222222222222', 'b@x.test'), ('33333333-3333-3333-3333-333333333333', 'c@x.test');
insert into public.communities (id, slug, name, owner_user_id, chat_enabled) values ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'chat-test-270', 'Chat test', '11111111-1111-1111-1111-111111111111', true);
insert into public.community_members (community_id, user_id, status, role) values ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111', 'active', 'owner'), ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '22222222-2222-2222-2222-222222222222', 'active', 'member'), ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '33333333-3333-3333-3333-333333333333', 'active', 'member');
insert into public.community_chat_groups (id, community_id, name, created_by) values ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Crew', '11111111-1111-1111-1111-111111111111');
insert into public.community_chat_group_members (group_id, user_id, community_id, role) values ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '11111111-1111-1111-1111-111111111111', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'owner'), ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '22222222-2222-2222-2222-222222222222', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'member');
insert into public.community_chat_group_messages (group_id, community_id, author_id, body, client_id) values ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111', 'hello', 'client-0001');
select 'member_count after two adds = ' || member_count from public.community_chat_groups where id = 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb';
savepoint dup;
insert into public.community_chat_group_messages (group_id, community_id, author_id, body, client_id) values ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '11111111-1111-1111-1111-111111111111', 'hello again', 'client-0001');
rollback to savepoint dup;
set local role authenticated;
select set_config('request.jwt.claim.sub', '22222222-2222-2222-2222-222222222222', true);
select 'b in group: ' || public.community_in_group('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb') || ', b sees messages: ' || (select count(*) from public.community_chat_group_messages) || ', b topic ok: ' || public.community_chat_topic_ok('chat:group:bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb') || ', bad topic: ' || public.community_chat_topic_ok('chat:group:nope');
select set_config('request.jwt.claim.sub', '33333333-3333-3333-3333-333333333333', true);
select 'c in group: ' || public.community_in_group('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb') || ', c sees messages: ' || (select count(*) from public.community_chat_group_messages) || ', c sees groups: ' || (select count(*) from public.community_chat_groups) || ', c topic ok: ' || public.community_chat_topic_ok('chat:group:bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb');
select set_config('realtime.topic', 'chat:group:bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', true);
select 'c reads typing rows: ' || (select count(*) from realtime.messages);
reset role;
insert into realtime.messages (topic, extension, payload) values ('chat:group:bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'broadcast', '{}');
set local role authenticated;
select set_config('request.jwt.claim.sub', '22222222-2222-2222-2222-222222222222', true);
select 'b reads typing rows: ' || (select count(*) from realtime.messages);
select set_config('request.jwt.claim.sub', '33333333-3333-3333-3333-333333333333', true);
select 'c reads typing rows: ' || (select count(*) from realtime.messages);
select 'c reads settings: ' || (select count(*) from public.community_chat_settings);
rollback;
